<script setup>
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue';
import axios from 'axios';
import {Plus,CalendarDays,ChevronLeft,ChevronRight,RefreshCw,Pencil,GripVertical,ArrowUpRight,Building2,X,MessageSquare,ChevronDown,ChevronUp} from '@lucide/vue';
import {calendarClock,calendarInitialMinute,calendarMinute,calendarTimeInput,mobileScheduleHandoffFields,layoutMobileCalendar,localCalendarDay,shiftCalendarDay} from './mobileCalendar.js';
import MobileIdentityAvatar from './MobileIdentityAvatar.vue';
import MobilePersonProfile from './MobilePersonProfile.vue';
import {formatPhoneForDisplay} from '../utils/phoneDisplay.js';
import {readMobileViewPreference,writeMobileViewPreference} from './mobileViewPreferences.js';
import SecureSessionCommentButton from '../components/session-comments/SecureSessionCommentButton.vue';
const props=defineProps({apiBase:String,sessionToken:String,userId:[String,Number],agencyId:[String,Number],timeZone:{type:String,default:()=>Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/Denver'},visible:{type:Boolean,default:true},showIntro:{type:Boolean,default:true}});
const emit=defineEmits(['open','comments','message','open-full','compose-email','intro-dismiss']);
const root=ref(null),sticky=ref(null),profile=ref(null),toolsCollapsed=ref(readMobileViewPreference(props.userId,'calendar','toolsCollapsed',!props.showIntro));
const day=ref(localCalendarDay(new Date(),props.timeZone)),mode=ref('day'),office=ref(false),items=ref([]),officeData=ref({}),officeId=ref(''),loading=ref(false),error=ref(''),notice=ref(''),scroller=ref(null),grid=ref(null),selection=ref(null),editor=ref(null),editorOptions=ref({agencies:[],clients:[],services:[],locations:[]}),editorLoading=ref(false),saving=ref(false),editorError=ref(''),sameDayWarning=ref(false),cancelReason=ref('');
let version=0,editorVersion=0,drag=null,timer,observer,positionFrame=0,positionEpoch=0,pendingPosition=false,userScrolling=false;const cache=new Map(),positions=new Map();
const positionKey=()=>`${props.agencyId}:${day.value}`;const phone=person=>formatPhoneForDisplay(person.workPhone,person.workPhoneExtension);
function rememberPosition(key=positionKey()){if(scroller.value&&props.visible&&!office.value&&mode.value==='day'&&!pendingPosition)positions.set(key,scroller.value.scrollTop);}
function measure(){if(pendingPosition)queuePosition();}
function collapseTools(){toolsCollapsed.value=true;writeMobileViewPreference(props.userId,'calendar','toolsCollapsed',true);}
function toggleTools(){toolsCollapsed.value=!toolsCollapsed.value;writeMobileViewPreference(props.userId,'calendar','toolsCollapsed',toolsCollapsed.value);}
function onUserScroll(){if(!userScrolling)return;pendingPosition=false;positions.set(positionKey(),scroller.value.scrollTop);collapseTools();if(props.showIntro)emit('intro-dismiss');}
function resetToday(){rememberPosition();office.value=false;day.value=localCalendarDay(new Date(),props.timeZone);mode.value='day';positions.delete(positionKey());void positionDay();}
defineExpose({resetToday});const config=()=>({headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true});
const dayLabel=computed(()=>new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(`${day.value}T12:00:00Z`)));
const title=item=>item.hasClient?`${item.clientMaskedName || item.clientInitials || 'Client session'}${item.serviceCode?' · '+item.serviceCode:''}`:item.title || 'Schedule event';
const clock=value=>calendarClock(value,props.timeZone);
const layout=computed(()=>layoutMobileCalendar(items.value,day.value,props.timeZone));const allDay=computed(()=>items.value.filter(item=>item.allDay));const filteredOffices=computed(()=>!officeId.value?officeData.value.offices || []:(officeData.value.offices || []).filter(row=>Number(row.id)===Number(officeId.value)));const currentService=computed(()=>editorOptions.value.services?.find(row=>Number(row.id)===Number(editor.value?.tenantServiceId)));
function applyPosition(epoch){if(epoch!==positionEpoch||!props.visible||office.value||mode.value!=='day'||!scroller.value)return;const target=positions.get(positionKey())??calendarInitialMinute(items.value,day.value,props.timeZone)*1.2;scroller.value.scrollTop=target; // Reapply when a hidden mounted surface gains a real viewport.
 if(scroller.value.clientHeight>0)pendingPosition=false;}
function queuePosition(){if(typeof requestAnimationFrame!=='function')return;cancelAnimationFrame(positionFrame);const epoch=positionEpoch;positionFrame=requestAnimationFrame(()=>{applyPosition(epoch);positionFrame=requestAnimationFrame(()=>applyPosition(epoch));});}
async function positionDay(){pendingPosition=true;userScrolling=false;const epoch=++positionEpoch;await nextTick();applyPosition(epoch);queuePosition();}
async function load(force=false){const key=`${props.agencyId}:${day.value}:${office.value}`,cached=cache.get(key),request=++version,token=props.sessionToken;if(cached){if(office.value)officeData.value=cached.data;else items.value=cached.data.items || [];if(!force&&Date.now()-cached.at<60000){loading.value=false;await positionDay();return;}}else{items.value=[];officeData.value={};}loading.value=true;error.value='';try{const {data}=await axios.get(`${props.apiBase}/${office.value?'office':'calendar/day'}`,{...config(),params:{day:day.value,timeZone:props.timeZone}});if(request!==version||token!==props.sessionToken)return;if(office.value)officeData.value=data;else items.value=data.items || [];cache.set(key,{data,at:Date.now()});if(cache.size>8)cache.delete(cache.keys().next().value);await positionDay();}catch(e){if(request!==version)return;if([401,403,423].includes(e.response?.status)){cache.clear();items.value=[];officeData.value={};}error.value=e.response?.data?.error?.message || 'Your schedule could not be loaded. Try again.';}finally{if(request===version)loading.value=false;}}
async function moveDay(amount){day.value=shiftCalendarDay(day.value,amount);}
async function loadOptions(agencyId){const request=++editorVersion;editorLoading.value=true;editorError.value='';try{const {data}=await axios.get(`${props.apiBase}/schedule/options`,{...config(),params:{agencyId}});if(request!==editorVersion)return;editorOptions.value={...editorOptions.value,...data};}catch(e){if(request===editorVersion)editorError.value=e.response?.data?.error?.message || 'Scheduling choices could not load.';}finally{if(request===editorVersion)editorLoading.value=false;}}
async function newBooking(start=420,end=start+60){editor.value={action:'',agencyId:Number(props.agencyId),date:day.value,start:calendarTimeInput(start),end:calendarTimeInput(Math.min(1439,end)),tenantServiceId:'',clientIds:[],serviceLocationId:'',modality:'IN_PERSON',notes:'',othersPresentNames:'',recurrence:'ONCE',occurrenceCount:12,notificationMode:'default',videoRoomMode:'unique_session'};sameDayWarning.value=false;cancelReason.value='';await loadActions(editor.value.agencyId);}
async function loadActions(agencyId){const request=++editorVersion;editorLoading.value=true;editorError.value='';editorOptions.value={agencies:[],actions:[],clients:[],services:[],locations:[]};try{const {data}=await axios.get(`${props.apiBase}/schedule/actions`,{...config(),params:{agencyId}});if(request!==editorVersion)return;editorOptions.value=data;}catch(e){if(request===editorVersion)editorError.value=e.response?.data?.error?.message || 'Scheduling actions could not load.';}finally{if(request===editorVersion)editorLoading.value=false;}}
async function chooseScheduleAction(action){if(editorLoading.value||saving.value||!editorOptions.value.actions?.some(row=>row.id===action.id))return;if(action.id==='individual_session'){editor.value.action=action.id;await loadOptions(editor.value.agencyId);return;}const selected=mobileScheduleHandoffFields({scheduleAction:action.id,scheduleDate:editor.value.date,scheduleStart:editor.value.start,scheduleEnd:editor.value.end,scheduleTimeZone:editor.value.timeZone||props.timeZone});if(!selected.scheduleAction){editorError.value='Choose a valid date and start/end times.';return;}emit('open-full',{kind:'schedule',agencyId:Number(editor.value.agencyId),...selected});closeEditor();}
async function editBooking(item,minute=null){if(!item.appointmentId){emit('open-full',{kind:'schedule',agencyId:item.agencyId || props.agencyId});return;}const request=++editorVersion;editorLoading.value=true;editorError.value='';editor.value={id:item.appointmentId,agencyId:Number(item.agencyId || props.agencyId),date:day.value,start:'',end:'',clientIds:[]};sameDayWarning.value=false;cancelReason.value='';try{const {data}=await axios.get(`${props.apiBase}/schedule/appointments/${item.appointmentId}`,config());if(request!==editorVersion)return;const a=data.appointment,start=calendarMinute(a.startAt,a.sourceTimezone || props.timeZone),end=calendarMinute(a.endAt,a.sourceTimezone || props.timeZone);editor.value={...a,date:minute===null?start.day:day.value,start:calendarTimeInput(minute===null?start.minute:minute),end:calendarTimeInput(minute===null?end.minute:Math.min(1439,minute+Math.max(15,end.minute-start.minute))),clientIds:(a.participants || []).filter(p=>p.role==='client').map(p=>Number(p.clientId)),timeZone:minute===null?(a.sourceTimezone || props.timeZone):props.timeZone,recurrence:'ONCE'};await loadOptions(a.agencyId);}catch(e){editorError.value=e.response?.data?.error?.message || 'This appointment could not be opened.';}finally{editorLoading.value=false;}}
function closeEditor(){if(saving.value)return;++editorVersion;editor.value=null;editorError.value='';selection.value=null;}
async function save(){const e=editor.value;if(!e || saving.value || editorLoading.value)return;editorError.value='';if(!e.date||!e.start||!e.end||e.end<=e.start||!e.tenantServiceId||!e.clientIds?.length){editorError.value='Choose a service, client, and valid start/end times.';return;}saving.value=true;try{const body={agencyId:Number(e.agencyId),tenantServiceId:Number(e.tenantServiceId),serviceCode:currentService.value?.serviceCode || e.serviceCode,serviceLocationId:Number(e.serviceLocationId)||null,startAt:`${e.date} ${e.start}:00`,endAt:`${e.date} ${e.end}:00`,timeZone:e.timeZone || props.timeZone,modality:e.modality,notes:e.notes || '',othersPresentNames:e.othersPresentNames || '',notificationMode:e.notificationMode || 'default',videoRoomMode:e.videoRoomMode || 'unique_session',participants:e.clientIds.map(id=>({role:'client',clientId:Number(id),receivesReminders:true})),...(!e.id?{recurrence:e.recurrence,occurrenceCount:Number(e.occurrenceCount)}:{}),acknowledgeSameDayServices:sameDayWarning.value};await axios[e.id?'patch':'post'](`${props.apiBase}/schedule/appointments${e.id?'/'+e.id:''}`,body,config());cache.clear();notice.value=e.id?'Appointment updated.':'Appointment scheduled.';saving.value=false;closeEditor();await load(true);}catch(error){sameDayWarning.value=error.response?.data?.error?.code==='SAME_DAY_SERVICE_WARNING';const created=error.response?.data?.createdAppointmentIds;editorError.value=(error.response?.data?.error?.message || 'The appointment was not saved. Your entries are preserved.')+(created?.length?` Some appointments were created (${created.join(', ')}). Review the full schedule before retrying.`:'');if(created?.length){cache.clear();await load(true);}}finally{saving.value=false;}}
async function cancelBooking(){if(!editor.value?.id||saving.value||!cancelReason.value.trim())return;saving.value=true;editorError.value='';try{await axios.post(`${props.apiBase}/schedule/appointments/${editor.value.id}/cancel`,{reason:cancelReason.value.trim()},config());cache.clear();notice.value='Appointment canceled.';saving.value=false;closeEditor();await load(true);}catch(e){editorError.value=e.response?.data?.error?.message || 'The appointment could not be canceled.';}finally{saving.value=false;}}
function setService(){const service=currentService.value;if(!service)return;if(service.modality==='TELEHEALTH')editor.value.modality='TELEHEALTH';else if(service.modality==='IN_PERSON')editor.value.modality='IN_PERSON';}
function setLocation(){const location=editorOptions.value.locations?.find(p=>Number(p.id)===Number(editor.value.serviceLocationId));if(location)editor.value.modality=['02','10'].includes(String(location.placeOfService).padStart(2,'0'))?'TELEHEALTH':'IN_PERSON';}
function minuteAt(event){return Math.max(0,Math.min(1425,Math.floor((event.clientY-grid.value.getBoundingClientRect().top)/18)*15));}
function startDrag(event,item=null){if(event.button!==undefined&&event.button!==0)return;event.preventDefault();event.stopPropagation();drag={id:event.pointerId,node:event.currentTarget,start:minuteAt(event),item};event.currentTarget.setPointerCapture?.(event.pointerId);selection.value={start:drag.start,end:Math.min(1440,drag.start+60),moving:!!item};}
function moveDrag(event){if(!drag)return;const minute=minuteAt(event);selection.value=drag.item?{start:minute,end:Math.min(1440,minute+Math.max(15,calendarMinute(drag.item.endAt,props.timeZone).minute-calendarMinute(drag.item.startAt,props.timeZone).minute)),moving:true}:{start:Math.min(drag.start,minute),end:Math.min(1440,Math.max(drag.start,minute)+15)};}
function endDrag(){if(!drag)return;const current=drag,range=selection.value;drag=null;selection.value=null;if(current.item)void editBooking(current.item,range.start);else void newBooking(range.start,range.end);}
function cancelDrag(){drag=null;selection.value=null;}
watch([day,office,()=>props.agencyId],(value,previous)=>{if(previous&&!previous[1]&&mode.value==='day'&&scroller.value&&!pendingPosition)positions.set(`${previous[2]}:${previous[0]}`,scroller.value.scrollTop);void load();});watch(mode,(value,old)=>{if(old==='day'&&scroller.value&&!pendingPosition)positions.set(positionKey(),scroller.value.scrollTop);if(value==='day')void positionDay();});watch(()=>props.visible,value=>{if(value){measure();void load();}else if(scroller.value&&!office.value&&mode.value==='day'&&!pendingPosition)positions.set(positionKey(),scroller.value.scrollTop);});watch(()=>props.sessionToken,()=>{version++;editorVersion++;cache.clear();positions.clear();items.value=[];officeData.value={};editor.value=null;profile.value=null;if(props.visible)void load();});watch(notice,value=>{clearTimeout(timer);if(value)timer=setTimeout(()=>notice.value='',5000);});onMounted(()=>{measure();if(typeof ResizeObserver!=='undefined'){observer=new ResizeObserver(measure);for(const element of [sticky.value,root.value])if(element)observer.observe(element);}window.addEventListener('resize',measure);void load();});watch(scroller,element=>{if(element){observer?.observe(element);if(props.visible)void positionDay();}});onBeforeUnmount(()=>{version++;editorVersion++;cache.clear();positions.clear();clearTimeout(timer);observer?.disconnect();window.removeEventListener('resize',measure);if(typeof cancelAnimationFrame==='function')cancelAnimationFrame(positionFrame);});
</script>
<template>
 <section ref="root" class="mobile-calendar" aria-label="Your schedule"><div ref="sticky" class="calendar-sticky"><div class="calendar-heading"><strong>{{dayLabel}}</strong><button aria-label="Refresh schedule" :disabled="loading" @click="load(true)"><RefreshCw :size="17"/></button></div><div class="calendar-toolbar"><button aria-label="Previous day" @click="moveDay(-1)"><ChevronLeft :size="18"/></button><button @click="resetToday">Today</button><input type="date" v-model="day" aria-label="Calendar date" :title="timeZone"/><button aria-label="Next day" @click="moveDay(1)"><ChevronRight :size="18"/></button><button :aria-pressed="office" @click="office=!office"><Building2 :size="17"/>{{office?'My day':'Office'}}</button><button v-if="!office" class="tools-toggle" :aria-expanded="!toolsCollapsed" aria-label="Schedule display and actions" @click="toggleTools"><ChevronDown v-if="toolsCollapsed" :size="16"/><ChevronUp v-else :size="16"/></button></div><template v-if="!office"><div v-if="!toolsCollapsed" class="calendar-actions"><div class="modes"><button :aria-pressed="mode==='day'" @click="mode='day'">Day</button><button :aria-pressed="mode==='agenda'" @click="mode='agenda'">Agenda</button></div><button class="primary" @click="newBooking()"><Plus :size="16"/>Schedule</button><button @click="emit('open-full',{kind:'schedule',agencyId})"><ArrowUpRight :size="16"/>Full schedule</button></div><p v-if="showIntro&&!toolsCollapsed" class="hint">Tap a time to schedule. Drag a grip to select time or move an appointment, then review and save.</p></template></div>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><p v-if="loading&&!items.length&&!officeData.mySlots" class="calendar-loading" role="status">Loading your schedule…</p>
 <div class="calendar-content" :class="{'calendar-content-office':office}">
 <template v-if="!office"><div v-if="allDay.length" class="all-day"><div v-for="item in allDay" :key="item.id"><button @click="emit('open',item)">{{title(item)}} · All day</button><button v-if="item.appointmentId" type="button" :aria-label="`Session comments for ${title(item)}`" @click="emit('comments',item)">🔒 Session comments</button><SecureSessionCommentButton v-if="item.appointmentId" :appointment-id="item.appointmentId" :client-id="item.clientId" icon-only /></div></div>
 <div v-if="mode==='day'" ref="scroller" class="day-scroll" aria-label="24 hour day schedule" @wheel="userScrolling=true" @touchstart="userScrolling=true" @pointerdown="userScrolling=true" @keydown="userScrolling=true" @scroll="onUserScroll"><div ref="grid" class="day-grid"><div v-for="hour in 24" :key="hour" class="hour" :style="{top:(hour-1)*72+'px'}"><time>{{hour===1?'12 AM':hour<13?(hour-1)+' AM':hour===13?'12 PM':(hour-13)+' PM'}}</time><button class="hour-slot" :aria-label="`Schedule at ${calendarTimeInput((hour-1)*60)}`" @click="newBooking((hour-1)*60)"></button><button class="range-grip" :aria-label="`Drag to select time from ${calendarTimeInput((hour-1)*60)}`" @pointerdown="startDrag" @pointermove="moveDrag" @pointerup="endDrag" @pointercancel="cancelDrag"><GripVertical :size="14"/></button></div><div v-if="selection" class="time-selection" :style="{top:selection.start*1.2+'px',height:(selection.end-selection.start)*1.2+'px'}">{{calendarTimeInput(selection.start)}}–{{calendarTimeInput(selection.end)}}</div><article v-for="row in layout" :key="row.item.id" class="event" :class="{reservation:row.item.kind==='OFFICE'}" :style="{top:row.start*1.2+'px',height:Math.max(22,(row.end-row.start)*1.2-3)+'px',left:`calc(51px + (100% - 55px) * ${row.column/row.columns})`,width:`calc((100% - 55px) / ${row.columns} - 3px)`}"><button class="event-open" @click="emit('open',row.item)"><strong>{{title(row.item)}}</strong><small>{{clock(row.item.startAt)}}–{{clock(row.item.endAt)}}</small><small v-if="row.item.location">{{row.item.location}}</small></button><div class="event-tools"><button v-if="row.item.appointmentId" type="button" class="event-comments-entry" :aria-label="`Session comments for ${title(row.item)}`" title="Session comments" @click="emit('comments',row.item)">🔒</button><SecureSessionCommentButton v-if="row.item.appointmentId" :appointment-id="row.item.appointmentId" :client-id="row.item.clientId" icon-only /><button :aria-label="`Edit ${title(row.item)}`" @click="editBooking(row.item)"><Pencil :size="13"/></button><button v-if="row.item.appointmentId" class="event-grip" :aria-label="`Drag to reschedule ${title(row.item)}`" @pointerdown="startDrag($event,row.item)" @pointermove="moveDrag" @pointerup="endDrag" @pointercancel="cancelDrag"><GripVertical :size="14"/></button></div></article></div></div>
 <div v-else class="agenda"><article v-for="item in items" :key="item.id"><button @click="emit('open',item)"><strong>{{title(item)}}</strong><small>{{item.allDay?'All day':clock(item.startAt)+'–'+clock(item.endAt)}}{{item.location?' · '+item.location:''}}</small></button><button v-if="item.appointmentId" type="button" :aria-label="`Session comments for ${title(item)}`" @click="emit('comments',item)">🔒 Session comments</button><SecureSessionCommentButton v-if="item.appointmentId" :appointment-id="item.appointmentId" :client-id="item.clientId" icon-only /><button :aria-label="`Edit ${title(item)}`" @click="editBooking(item)"><Pencil :size="16"/></button></article><p v-if="!loading&&!items.length">Nothing scheduled this day.</p></div></template>
 <template v-else><div class="office-filter"><button :aria-pressed="!officeId" @click="officeId=''">All offices</button><button v-for="location in officeData.locations || []" :key="location.id" :aria-pressed="Number(officeId)===Number(location.id)" @click="officeId=String(location.id)">{{location.label || location.name}}</button></div><h3>My office reservations</h3><p class="hint">Office space and recurring room assignments for this day.</p><article class="reservation-card" v-for="slot in (officeData.mySlots || []).filter(row=>!officeId||Number(row.office_id)===Number(officeId))" :key="slot.id"><strong>{{slot.office_name}}</strong><small>{{clock(slot.start_at)}}–{{clock(slot.end_at)}} · {{slot.availability || 'Office reservation'}}</small></article><p v-if="!loading&&!(officeData.mySlots || []).length">No office reservations this day.</p><h3>Who's in today</h3><article v-for="building in filteredOffices" :key="building.id" class="office-card"><strong>{{building.label || building.name}}</strong><small>{{building.people.length}} people · {{building.slotCount}} reservations</small><div v-for="person in building.people" :key="person.providerId" class="person"><button class="person-photo" :aria-label="`View ${person.name}`" @click="profile={id:person.providerId,agencyId:person.agencyId||agencyId}"><MobileIdentityAvatar :photo="person.profilePhotoUrl" :agency-icon="person.agencyLogoUrl" :name="person.name"/></button><span class="office-person-content"><span class="office-person-title"><button class="person-name" @click="profile={id:person.providerId,agencyId:person.agencyId||agencyId}">{{person.name}}</button><strong v-if="person.credential" class="credential">{{person.credential}}</strong></span><button v-if="person.email" class="person-email" @click="emit('compose-email',{to:person.email})">{{person.email}}</button><a v-if="person.workPhoneExtension&&phone(person).telHref" :href="phone(person).telHref">Ext. {{person.workPhoneExtension}}</a><small v-if="person.agencyName">{{person.agencyName}}</small><small>{{clock(person.firstStart)}}–{{clock(person.lastEnd)}}{{person.rooms.length?' · '+person.rooms.join(', '):''}}</small></span><button @click="emit('message',person.providerId)"><MessageSquare :size="15"/>Message</button></div></article></template>
 </div>
