 <Teleport to="body"><div v-if="editor" class="schedule-editor-overlay" @click.self="closeEditor"><section role="dialog" aria-modal="true" aria-label="Schedule appointment" @keydown.esc="closeEditor"><header><h2>{{editor.id?'Edit appointment':editor.action?'Book Session':'Schedule'}}</h2><button aria-label="Close appointment" :disabled="saving" @click="closeEditor"><X :size="20"/></button></header><SecureSessionCommentButton v-if="editor.id" :appointment-id="editor.id" :client-id="editor.clientIds?.length===1 ? editor.clientIds[0] : null" :disabled="editorLoading" /><p v-if="editorLoading" role="status">Loading scheduling choices…</p><p v-if="editorError" class="error" role="alert">{{editorError}}</p><div v-if="!editor.id&&!editor.action" class="schedule-action-chooser"><label>Agency<select v-model="editor.agencyId" :disabled="editorLoading" @change="loadActions(Number(editor.agencyId))"><option v-for="agency in editorOptions.agencies" :key="agency.id" :value="agency.id">{{agency.name}}</option></select></label><div class="editor-times"><label>Date<input type="date" v-model="editor.date" required/></label><label>Start<input type="time" v-model="editor.start" required/></label><label>End<input type="time" v-model="editor.end" required/></label></div><small>Times in {{editor.timeZone || timeZone}}</small><h3>What would you like to do?</h3><div class="schedule-action-grid"><button v-for="action in editorOptions.actions || []" :key="action.id" type="button" :data-schedule-action="action.id" :disabled="editorLoading" @click="chooseScheduleAction(action)"><strong>{{action.label}}</strong><small>{{action.description}}</small><ArrowUpRight v-if="!action.compact" :size="16" aria-label="Opens full schedule"/></button></div></div><form v-if="editor.id||editor.action" @submit.prevent="save"><button v-if="!editor.id" type="button" class="back-actions" @click="editor.action='';loadActions(editor.agencyId)">‹ All actions</button><label>Agency<select v-model="editor.agencyId" :disa